 U.append({'id':SID+'-'+i,'source_unit_id':SID+'-'+i,'source_role':role,'pdf_page':p,'printed_page':13204+p if role=='main'else 'S-'+str(p),'locator':loc,'kind':kind,'claim':claim,'disposition':disposition})
